<style>
body:has(.nt-about-page){margin:0}.nt-about-page{color:var(--nt-ink);background:#fff}.nt-about-page *{box-sizing:border-box}.nt-about-page a{text-decoration:none;color:inherit}.nt-about-page a:focus-visible{outline:2px solid var(--nt-gold);outline-offset:5px}.nt-about-page h1,.nt-about-page h2,.nt-about-page h3{font-family:var(--nt-serif)}.nt-about-page figure{margin:0}.nt-about-hero{padding:30px 0 64px;background:var(--nt-paper)}.nt-about-breadcrumb{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:#746b5d;margin-bottom:36px}.nt-about-hero-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.05fr);gap:64px;align-items:center}.nt-about-kicker{margin:0 0 22px;font-size:11px;letter-spacing:.15em;text-transform:uppercase;font-weight:700;color:#8a682d}.nt-about-intro h1{font-size:clamp(38px,4.5vw,64px);line-height:1.12;letter-spacing:-.035em;margin:0 0 26px;color:var(--nt-dark)}.nt-about-lead{max-width:550px;font-size:16px;line-height:1.85;color:#6d6559;margin:0 0 30px}.nt-about-button{display:inline-flex;align-items:center;justify-content:center;gap:28px;min-height:54px;padding:16px 28px;border-radius:40px;background:var(--nt-gold);color:#302e27!important;font-size:13px;font-weight:700;transition:background .2s}.nt-about-button:hover{background:#e4c58b}.nt-about-cover{position:relative;aspect-ratio:1.1;border-radius:5px;overflow:hidden}.nt-about-cover img{width:100%;height:100%;object-fit:cover}.nt-about-cover figcaption{position:absolute;inset:auto 0 0;padding:50px 26px 24px;color:#fff;background:linear-gradient(transparent,rgba(23,22,18,.7));font-size:12px}.nt-about-story{display:grid;grid-template-columns:minmax(0,.65fr) minmax(0,1fr);gap:90px;padding-top:88px;padding-bottom:70px;align-items:start}.nt-about-story-heading{position:sticky;top:30px}.nt-about-story-heading h2,.nt-about-explore h2{margin:0 0 24px;color:var(--nt-dark);font-size:clamp(28px,3vw,38px);line-height:1.25;letter-spacing:-.025em}.nt-about-story-heading>p:last-of-type{font-size:14px;line-height:1.9;color:#746b5d;max-width:360px}.nt-about-text-link{display:inline-flex;gap:26px;padding:14px 0;margin-top:10px;border-bottom:1px solid #c5bcae;font-size:13px;font-weight:600}.nt-about-rich{font-size:16px;line-height:1.9;color:#665e52;overflow-wrap:anywhere}.nt-about-rich h2,.nt-about-rich h3{font-size:25px;line-height:1.35;color:var(--nt-dark);margin:32px 0 18px}.nt-about-rich>:first-child{margin-top:0}.nt-about-rich p{margin:0 0 22px}.nt-about-rich img{max-width:100%;height:auto;border-radius:5px}.nt-about-rich table{display:block;max-width:100%;overflow:auto}.nt-about-rich blockquote{margin:24px 0;padding:16px 24px;background:var(--nt-paper);border-left:3px solid var(--nt-gold)}.nt-about-rich a{color:#8a682d;text-decoration:underline}.nt-about-explore{padding-top:35px;padding-bottom:80px;border-top:1px solid #ebe5da}.nt-about-explore header{margin-bottom:34px}.nt-about-explore .nt-about-kicker{margin-bottom:14px}.nt-about-explore-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.nt-about-explore-card{display:block;padding:30px;background:var(--nt-paper);border:1px solid #ece5d9;border-radius:5px;transition:background .2s}.nt-about-explore-card:hover{background:#eee7da}.nt-about-card-number{display:flex;justify-content:space-between;font-family:var(--nt-serif);font-size:23px;color:#8a682d;margin-bottom:32px}.nt-about-explore-card h3{margin:0 0 15px;font-size:25px;line-height:1.35}.nt-about-explore-card p{margin:0;color:#746b5d;font-size:14px;line-height:1.85}.nt-about-cta{padding:60px 0;background:#eae0cd}.nt-about-cta>.nt-container{display:flex;justify-content:space-between;align-items:center;gap:32px}.nt-about-cta .nt-about-kicker{margin-bottom:14px}.nt-about-cta h2{font-size:clamp(28px,3vw,40px);line-height:1.25;margin:0 0 14px}.nt-about-cta p:last-child{margin:0;color:#746b5d;font-size:14px}.nt-about-cta .nt-about-button{flex-shrink:0}
@media(max-width:900px){.nt-about-hero-grid{gap:32px}.nt-about-story{gap:40px}.nt-about-explore-grid{gap:16px}.nt-about-explore-card{padding:24px}.nt-about-explore-card h3{font-size:22px}}
@media(max-width:650px){.nt-about-hero-grid,.nt-about-story,.nt-about-explore-grid{grid-template-columns:1fr}.nt-about-hero{padding-bottom:40px}.nt-about-intro h1{font-size:40px}.nt-about-lead{font-size:15px}.nt-about-cover{aspect-ratio:1.3}.nt-about-story{padding-top:48px;padding-bottom:46px;gap:32px}.nt-about-story-heading{position:static}.nt-about-rich{font-size:15px}.nt-about-explore{padding-bottom:48px}.nt-about-explore-card{padding:26px}.nt-about-card-number{margin-bottom:24px}.nt-about-cta{padding:42px 0}.nt-about-cta>.nt-container{display:block}.nt-about-cta .nt-about-button{margin-top:26px}body:has(.nt-about-page) .foot-header__masthead-inner{gap:12px;flex-wrap:wrap}body:has(.nt-about-page) .foot-brand img{max-width:130px}body:has(.nt-about-page) .foot-header__account{gap:6px;flex-wrap:wrap}body:has(.nt-about-page) .foot-header__account button{font-size:11px;white-space:nowrap}}
@media(prefers-reduced-motion:reduce){.nt-about-button,.nt-about-explore-card{transition:none}}
